create table ai_chat_messages (created_at datetime(6) not null, id bigint not null auto_increment, thread_id bigint not null, role varchar(20) not null, model varchar(120), actions_json LONGTEXT not null, content LONGTEXT not null, references_json LONGTEXT not null, primary key (id)) engine=InnoDB;
create table ai_chat_threads (message_count integer not null, created_at datetime(6) not null, id bigint not null auto_increment, last_message_at datetime(6), updated_at datetime(6) not null, user_id bigint not null, last_message_role varchar(20), title varchar(180) not null, last_message_preview varchar(500), primary key (id)) engine=InnoDB;
create table cart_items (quantity integer not null, unit_price decimal(12,2) not null, cart_id bigint not null, created_at datetime(6) not null, dish_id bigint not null, id bigint not null auto_increment, store_id bigint not null, updated_at datetime(6) not null, primary key (id)) engine=InnoDB;
create table carts (created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6) not null, user_id bigint not null, status enum ('OPEN') not null, primary key (id)) engine=InnoDB;
create table categories (active bit not null, sort_order integer, created_at datetime(6) not null, id bigint not null auto_increment, store_id bigint, updated_at datetime(6) not null, name varchar(120) not null, description varchar(1000), primary key (id)) engine=InnoDB;
create table category_image_paths (sort_order integer not null, category_id bigint not null, image_path varchar(500), primary key (sort_order, category_id)) engine=InnoDB;
create table content_section_image_paths (sort_order integer not null, content_section_id bigint not null, image_path varchar(500), primary key (sort_order, content_section_id)) engine=InnoDB;
