create table customer_feedbacks (created_at datetime(6) not null, id bigint not null auto_increment, related_order_id bigint, related_store_id bigint, replied_at datetime(6), replied_by_user_id bigint, updated_at datetime(6) not null, user_id bigint not null, replied_by_user_name varchar(180), subject varchar(180) not null, message varchar(3000) not null, reply_message varchar(3000), category enum ('APP_EXPERIENCE','DELIVERY','GENERAL','ORDER_EXPERIENCE','OTHER','PRODUCT_QUALITY','STORE_SERVICE') not null, replied_by_user_role enum ('ADMIN','MANAGER','SHIPPER','USER'), primary key (id)) engine=InnoDB;
