create table dishes (active bit not null, available bit not null, franchise_required bit not null, price decimal(12,2) not null, category_id bigint not null, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6) not null, status varchar(50), name varchar(150) not null, franchise_note varchar(1000), highlight_summary varchar(1000), note varchar(1000), description varchar(2000), primary key (id)) engine=InnoDB;
create table email_otps (used bit not null, created_at datetime(6) not null, expires_at datetime(6) not null, id bigint not null auto_increment, otp_code varchar(8) not null, used_at datetime(6), user_id bigint not null, purpose enum ('PASSWORD_RESET','REGISTER_VERIFY'), primary key (id)) engine=InnoDB;
create table employee_attendances (work_date date not null, check_in_at datetime(6) not null, check_out_at datetime(6), created_at datetime(6) not null, id bigint not null auto_increment, store_id bigint not null, updated_at datetime(6) not null, user_id bigint not null, work_schedule_id bigint, employee_role enum ('ADMIN','MANAGER','SHIPPER','USER') not null, primary key (id)) engine=InnoDB;
