create table order_items (quantity integer not null, unit_price decimal(12,2) not null, created_at datetime(6) not null, dish_id bigint not null, id bigint not null auto_increment, order_id bigint not null, store_id bigint not null, updated_at datetime(6) not null, primary key (id)) engine=InnoDB;
create table order_promotion_dish_ids (sort_order integer not null, dish_id bigint not null, order_id bigint not null, primary key (sort_order, order_id)) engine=InnoDB;
