create table orders (discount_amount decimal(12,2) not null, promotion_eligible_amount decimal(12,2), subtotal_amount decimal(12,2) not null, total_amount decimal(12,2) not null, confirmed_at datetime(6), confirmed_by_user_id bigint, created_at datetime(6) not null, delivering_shipper_id bigint, delivery_address_id bigint, delivery_proof_captured_at datetime(6), delivery_proof_uploaded_at datetime(6), id bigint not null auto_increment, invoice_issued_at datetime(6), paid_at datetime(6), payment_expires_at datetime(6), payos_order_code bigint, preparing_staff_id bigint, scheduled_delivery_at datetime(6), updated_at datetime(6) not null, user_id bigint not null, delivery_phone_number varchar(30), payment_provider varchar(30), promotion_code varchar(50), delivery_full_name varchar(100), payment_link_id varchar(100), payment_reference varchar(100), invoice_number varchar(120), delivery_proof_image_path varchar(500), delivery_proof_note varchar(500), payment_cancel_url varchar(500), payment_checkout_url varchar(500), payment_return_url varchar(500), payment_qr_code varchar(4000), delivery_address varchar(255), invoice_qr_token varchar(255), delivery_type enum ('IMMEDIATE','SCHEDULED') not null, payment_status enum ('CANCELLED','FAILED','PAID','PENDING') not null, promotion_scope enum ('DISH','ORDER'), status enum ('CANCELLED','COMPLETED','CONFIRMED','OUT_FOR_DELIVERY','PENDING','PREPARING','READY_FOR_SHIPPER') not null, primary key (id)) engine=InnoDB;
