create table promotions (active bit not null, discount_value decimal(12,2) not null, max_discount_amount decimal(12,2), min_cross_store_bill_amount decimal(12,2), min_order_amount decimal(12,2), min_store_bill_amount decimal(12,2), usage_limit integer, used_count integer not null, created_at datetime(6) not null, ends_at datetime(6), id bigint not null auto_increment, starts_at datetime(6), updated_at datetime(6) not null, code varchar(50) not null, name varchar(150), description varchar(500), discount_type enum ('FIXED_AMOUNT','PERCENT') not null, scope enum ('DISH','ORDER') not null, primary key (id)) engine=InnoDB;
